from __future__ import annotations

from datetime import datetime
from pathlib import Path
import shutil
import sys


REPO_ROOT = Path(__file__).resolve().parents[1]
TARGET = REPO_ROOT / "agents" / "news_agent" / "event_store.py"
BACKUP_DIR = REPO_ROOT / "dev-snapshots"

INSERT_MARKER = '\n    def get_event_evidence(self, event_id):\n'
METHODS_BLOCK = '\n    @staticmethod\n    def _normalize_satellite_choice(\n        value,\n        *,\n        field_name,\n        allowed_values,\n    ):\n        if value not in allowed_values:\n            allowed = ", ".join(sorted(allowed_values))\n            raise ValueError(\n                f"{field_name} must be one of: {allowed}"\n            )\n\n        return value\n\n    @staticmethod\n    def _normalize_satellite_bbox(\n        bbox_min_lon,\n        bbox_min_lat,\n        bbox_max_lon,\n        bbox_max_lat,\n    ):\n        values = (\n            bbox_min_lon,\n            bbox_min_lat,\n            bbox_max_lon,\n            bbox_max_lat,\n        )\n\n        if all(value is None for value in values):\n            return (None, None, None, None)\n\n        if any(value is None for value in values):\n            raise ValueError(\n                "bbox must provide all four values or none"\n            )\n\n        min_lon = float(bbox_min_lon)\n        min_lat = float(bbox_min_lat)\n        max_lon = float(bbox_max_lon)\n        max_lat = float(bbox_max_lat)\n\n        if not -180.0 <= min_lon <= 180.0:\n            raise ValueError(\n                "bbox_min_lon must be between -180 and 180"\n            )\n\n        if not -180.0 <= max_lon <= 180.0:\n            raise ValueError(\n                "bbox_max_lon must be between -180 and 180"\n            )\n\n        if not -90.0 <= min_lat <= 90.0:\n            raise ValueError(\n                "bbox_min_lat must be between -90 and 90"\n            )\n\n        if not -90.0 <= max_lat <= 90.0:\n            raise ValueError(\n                "bbox_max_lat must be between -90 and 90"\n            )\n\n        if min_lon > max_lon:\n            raise ValueError(\n                "bbox_min_lon must not exceed bbox_max_lon"\n            )\n\n        if min_lat > max_lat:\n            raise ValueError(\n                "bbox_min_lat must not exceed bbox_max_lat"\n            )\n\n        return (\n            min_lon,\n            min_lat,\n            max_lon,\n            max_lat,\n        )\n\n    @staticmethod\n    def _satellite_row_to_record(row):\n        import json\n\n        bbox = None\n\n        if any(\n            value is not None\n            for value in row[11:15]\n        ):\n            bbox = {\n                "min_lon": row[11],\n                "min_lat": row[12],\n                "max_lon": row[13],\n                "max_lat": row[14],\n            }\n\n        geometry = (\n            json.loads(row[10])\n            if row[10]\n            else None\n        )\n\n        provenance = (\n            json.loads(row[20])\n            if row[20]\n            else None\n        )\n\n        return {\n            "id": row[0],\n            "information_type": row[1],\n            "derivation_level": row[2],\n            "observation_type": row[3],\n            "sensor": row[4],\n            "platform": row[5],\n            "dataset_id": row[6],\n            "source_image_id": row[7],\n            "acquisition_time": row[8],\n            "processing_time": row[9],\n            "geometry": geometry,\n            "bbox": bbox,\n            "confidence": row[15],\n            "review_status": row[16],\n            "processing_version": row[17],\n            "processing_method": row[18],\n            "cache_reference": row[19],\n            "provenance": provenance,\n            "created_at": row[21],\n            "updated_at": row[22],\n        }\n\n    def create_satellite_observation(\n        self,\n        *,\n        observation_type,\n        sensor,\n        dataset_id,\n        source_image_id,\n        acquisition_time,\n        derivation_level="processed",\n        platform=None,\n        processing_time=None,\n        geometry=None,\n        bbox_min_lon=None,\n        bbox_min_lat=None,\n        bbox_max_lon=None,\n        bbox_max_lat=None,\n        confidence=None,\n        review_status="unreviewed",\n        processing_version="0.1",\n        processing_method=None,\n        cache_reference=None,\n        provenance=None,\n    ):\n        import json\n\n        required_strings = {\n            "observation_type": observation_type,\n            "sensor": sensor,\n            "dataset_id": dataset_id,\n            "source_image_id": source_image_id,\n            "processing_version": processing_version,\n        }\n\n        for field_name, value in required_strings.items():\n            if not isinstance(value, str) or not value.strip():\n                raise ValueError(\n                    f"{field_name} must be a non-empty string"\n                )\n\n        derivation_level = self._normalize_satellite_choice(\n            derivation_level,\n            field_name="derivation_level",\n            allowed_values={\n                "raw",\n                "processed",\n                "derived",\n            },\n        )\n\n        review_status = self._normalize_satellite_choice(\n            review_status,\n            field_name="review_status",\n            allowed_values={\n                "unreviewed",\n                "review_required",\n                "reviewed",\n                "rejected",\n            },\n        )\n\n        acquisition_time = self._normalize_optional_datetime(\n            acquisition_time\n        )\n\n        if acquisition_time is None:\n            raise ValueError(\n                "acquisition_time is required"\n            )\n\n        processing_time = self._normalize_optional_datetime(\n            processing_time\n        )\n\n        confidence = self._normalize_confidence(\n            confidence\n        )\n\n        (\n            bbox_min_lon,\n            bbox_min_lat,\n            bbox_max_lon,\n            bbox_max_lat,\n        ) = self._normalize_satellite_bbox(\n            bbox_min_lon,\n            bbox_min_lat,\n            bbox_max_lon,\n            bbox_max_lat,\n        )\n\n        if geometry is not None and not isinstance(\n            geometry,\n            dict,\n        ):\n            raise ValueError(\n                "geometry must be a dict or None"\n            )\n\n        if provenance is not None and not isinstance(\n            provenance,\n            dict,\n        ):\n            raise ValueError(\n                "provenance must be a dict or None"\n            )\n\n        geometry_geojson = (\n            json.dumps(\n                geometry,\n                ensure_ascii=False,\n                sort_keys=True,\n            )\n            if geometry is not None\n            else None\n        )\n\n        provenance_json = (\n            json.dumps(\n                provenance,\n                ensure_ascii=False,\n                sort_keys=True,\n            )\n            if provenance is not None\n            else None\n        )\n\n        observation_id = (\n            "satobs_" + str(uuid4())\n        )\n\n        now = datetime.now(\n            timezone.utc\n        ).isoformat()\n\n        with self._connect() as connection:\n            connection.execute(\n                """\n                INSERT INTO satellite_observations (\n                    id,\n                    information_type,\n                    derivation_level,\n                    observation_type,\n                    sensor,\n                    platform,\n                    dataset_id,\n                    source_image_id,\n                    acquisition_time,\n                    processing_time,\n                    geometry_geojson,\n                    bbox_min_lon,\n                    bbox_min_lat,\n                    bbox_max_lon,\n                    bbox_max_lat,\n                    confidence,\n                    review_status,\n                    processing_version,\n                    processing_method,\n                    cache_reference,\n                    provenance_json,\n                    created_at,\n                    updated_at\n                )\n                VALUES (\n                    ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?,\n                    ?, ?, ?, ?, ?, ?, ?, ?, ?, ?\n                )\n                """,\n                (\n                    observation_id,\n                    "satellite_observation",\n                    derivation_level,\n                    observation_type.strip(),\n                    sensor.strip(),\n                    platform,\n                    dataset_id.strip(),\n                    source_image_id.strip(),\n                    acquisition_time,\n                    processing_time,\n                    geometry_geojson,\n                    bbox_min_lon,\n                    bbox_min_lat,\n                    bbox_max_lon,\n                    bbox_max_lat,\n                    confidence,\n                    review_status,\n                    processing_version.strip(),\n                    processing_method,\n                    cache_reference,\n                    provenance_json,\n                    now,\n                    now,\n                ),\n            )\n\n            connection.commit()\n\n        return observation_id\n\n    def get_satellite_observation(\n        self,\n        observation_id,\n    ):\n        with self._connect() as connection:\n            cursor = connection.cursor()\n\n            cursor.execute(\n                """\n                SELECT\n                    id,\n                    information_type,\n                    derivation_level,\n                    observation_type,\n                    sensor,\n                    platform,\n                    dataset_id,\n                    source_image_id,\n                    acquisition_time,\n                    processing_time,\n                    geometry_geojson,\n                    bbox_min_lon,\n                    bbox_min_lat,\n                    bbox_max_lon,\n                    bbox_max_lat,\n                    confidence,\n                    review_status,\n                    processing_version,\n                    processing_method,\n                    cache_reference,\n                    provenance_json,\n                    created_at,\n                    updated_at\n                FROM satellite_observations\n                WHERE id = ?\n                LIMIT 1\n                """,\n                (observation_id,),\n            )\n\n            row = cursor.fetchone()\n\n        if not row:\n            return None\n\n        return self._satellite_row_to_record(\n            row\n        )\n\n    def list_satellite_observations(self):\n        with self._connect() as connection:\n            cursor = connection.cursor()\n\n            cursor.execute(\n                """\n                SELECT\n                    id,\n                    information_type,\n                    derivation_level,\n                    observation_type,\n                    sensor,\n                    platform,\n                    dataset_id,\n                    source_image_id,\n                    acquisition_time,\n                    processing_time,\n                    geometry_geojson,\n                    bbox_min_lon,\n                    bbox_min_lat,\n                    bbox_max_lon,\n                    bbox_max_lat,\n                    confidence,\n                    review_status,\n                    processing_version,\n                    processing_method,\n                    cache_reference,\n                    provenance_json,\n                    created_at,\n                    updated_at\n                FROM satellite_observations\n                ORDER BY\n                    acquisition_time DESC,\n                    created_at DESC\n                """\n            )\n\n            rows = cursor.fetchall()\n\n        return [\n            self._satellite_row_to_record(\n                row\n            )\n            for row in rows\n        ]\n\n    def link_satellite_observation_to_event(\n        self,\n        *,\n        event_id,\n        satellite_observation_id,\n        relation_type,\n        relation_confidence=None,\n    ):\n        relation_type = self._normalize_satellite_choice(\n            relation_type,\n            field_name="relation_type",\n            allowed_values={\n                "spatial_overlap",\n                "temporal_match",\n                "contextual",\n                "analyst_linked",\n            },\n        )\n\n        relation_confidence = (\n            self._normalize_confidence(\n                relation_confidence\n            )\n        )\n\n        now = datetime.now(\n            timezone.utc\n        ).isoformat()\n\n        with self._connect() as connection:\n            event_exists = connection.execute(\n                """\n                SELECT 1\n                FROM events\n                WHERE id = ?\n                LIMIT 1\n                """,\n                (event_id,),\n            ).fetchone()\n\n            if event_exists is None:\n                raise ValueError(\n                    f"event not found: {event_id}"\n                )\n\n            observation_exists = connection.execute(\n                """\n                SELECT 1\n                FROM satellite_observations\n                WHERE id = ?\n                LIMIT 1\n                """,\n                (satellite_observation_id,),\n            ).fetchone()\n\n            if observation_exists is None:\n                raise ValueError(\n                    "satellite observation not found: "\n                    f"{satellite_observation_id}"\n                )\n\n            existing_link = connection.execute(\n                """\n                SELECT 1\n                FROM event_satellite_observations\n                WHERE event_id = ?\n                  AND satellite_observation_id = ?\n                LIMIT 1\n                """,\n                (\n                    event_id,\n                    satellite_observation_id,\n                ),\n            ).fetchone()\n\n            if existing_link is not None:\n                return False\n\n            connection.execute(\n                """\n                INSERT INTO event_satellite_observations (\n                    event_id,\n                    satellite_observation_id,\n                    relation_type,\n                    relation_confidence,\n                    created_at\n                )\n                VALUES (?, ?, ?, ?, ?)\n                """,\n                (\n                    event_id,\n                    satellite_observation_id,\n                    relation_type,\n                    relation_confidence,\n                    now,\n                ),\n            )\n\n            connection.commit()\n\n        return True\n\n'


def main() -> int:
    if not TARGET.exists():
        print(f"ERROR: target not found: {TARGET}")
        return 2

    text = TARGET.read_text(encoding="utf-8")

    if "def create_satellite_observation(" in text:
        print("SAT-3 CRUD already present; no edit applied.")
        return 0

    if INSERT_MARKER not in text:
        print(
            "ERROR: safe insertion marker was not found in event_store.py. "
            "No changes were made."
        )
        return 3

    BACKUP_DIR.mkdir(parents=True, exist_ok=True)
    stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    backup = BACKUP_DIR / f"event_store.before_sat3_crud_v01_{stamp}.py"
    shutil.copy2(TARGET, backup)

    updated = text.replace(
        INSERT_MARKER,
        METHODS_BLOCK + INSERT_MARKER,
        1,
    )

    TARGET.write_text(updated, encoding="utf-8")

    print("SAT-3 SatelliteObservation CRUD v0.1 installed.")
    print(f"Modified: {TARGET.relative_to(REPO_ROOT)}")
    print(f"Backup: {backup.relative_to(REPO_ROOT)}")
    print("Run syntax and targeted tests before committing.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
